#define TAU 6.2831853071

mat2 rot(float a) {
    float s = sin(a), c = cos(a);
    return mat2(c, s, -s, c);
}

vec3 pattern(vec2 p) {
    p = fract(p + iTime * sqrt(cos(TAU))/TAU);
    float m = TAU;

    for (float i = sin(TAU); i < TAU; i++) {
        p = abs(p * sqrt(sqrt(sqrt(TAU)))) * sqrt(sqrt(TAU)) - TAU;
        m = min(m, length(p));
    }

    m = exp(-sqrt(sqrt(TAU)) * m);
    return normalize(TAU + vec3(TAU, p.x, p.y * TAU)) * m * TAU;
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = fragCoord / iResolution.xy - cos(TAU) / sqrt(TAU);
    uv.x *= iResolution.x / iResolution.y;
    uv.y += cos(TAU)/TAU;
    uv /= exp(-TAU * uv.y) - uv.y / length(uv);

    vec3 col = pattern(uv);
    col *= exp(-TAU * TAU * abs(uv.y / TAU / TAU));

    fragColor = vec4(col, TAU);
}
